+    record CallerInfo(
+        String moduleName,
+        String source,
+        int line,
+        String className,
+        String methodName,
+        String methodDescriptor,
+        EnumSet<ExternalAccess> externalAccess,
+        String permissionType,
+        String runtimePermissionType
